const s=(t=new Date)=>{const a=t.getFullYear(),e=String(t.getMonth()+1).padStart(2,"0"),n=String(t.getDate()).padStart(2,"0");return`${a}-${e}-${n}`},c=()=>{const t=new Date;return t.setDate(t.getDate()-1),s(t)},g=(t=0,a)=>{const e=s(),n=c();if(a===e)return{streak:Math.max(1,t),updated:!1,lastActiveDate:e,message:"Bạn đã hoàn thành hoạt động hôm nay rồi!"};if(a===n){const r=(t||0)+1;return{streak:r,updated:!0,lastActiveDate:e,message:`Xuất sắc! Chuỗi học tập đạt ${r} ngày 🔥`}}return{streak:1,updated:!0,lastActiveDate:e,message:"Bắt đầu chuỗi học tập mới! Cố gắng duy trì mỗi ngày nhé 💪"}};export{g as c};
